// 記帳訂正は金額と勘定科目が同じ表に並ぶため、UIがセル名や正答値から推測しないよう
// 問題形式の契約として入力種別を明示する（全E001〜E020で共通）。
const correctionInputTypes = Object.freeze({ debitAccount: 'account', debitAmount: 'amount', creditAccount: 'account', creditAmount: 'amount' });
for (let n = 1; n <= 20; n += 1) {
  const question = QuestionData[`E${String(n).padStart(3, '0')}`];
  if (question?.table) question.table.inputTypes = correctionInputTypes;
}
// 財務諸表問題では資産合計と負債・純資産合計を別々に回答できる行を用意する。
for (let n = 1; n <= 10; n += 1) {
  const question = QuestionData[`F${String(n).padStart(3, '0')}`];
  if (question?.category === '貸借対照表') question.format = 'balance-sheet';
  const totalRow = question?.table?.rows?.find(row => row.amount === '入力' && String(row.account).includes('資産合計／'));
  if (totalRow) {
    totalRow.account = '資産合計';
    question.table.rows.push({ section: '合計', account: '負債・純資産合計', amount: '入力' });
  }
  let inputIndex = 0;
  for (const row of question?.table?.rows || []) if (row.amount === '入力') row.inputCellId = question.table.inputCells[inputIndex++];
}

// 第6次教材監査: 数字差替え型の既存問題を、公式区分の不足していた記帳行動へ置換する。
// IDとtype別件数を維持し、学習履歴との互換性を保つ。
const worksheetRows = [
  ['現金', [300000,0,0,0,0,0,300000,0]], ['売掛金', [300000,0,0,0,0,0,300000,0]],
  ['繰越商品', [200000,0,0,0,0,0,200000,0]], ['備品', [600000,0,0,0,0,0,600000,0]],
  ['買掛金', [0,200000,0,0,0,0,0,200000]], ['資本金', [0,1000000,0,0,0,0,0,1000000]],
  ['売上', [0,800000,0,0,0,800000,0,0]], ['仕入', [400000,0,0,0,400000,0,0,0]],
  ['保険料', [200000,0,0,40000,160000,0,0,0]], ['前払保険料', [0,0,40000,0,0,0,40000,0]],
  ['減価償却費', [0,0,60000,0,60000,0,0,0]], ['減価償却累計額', [0,0,0,60000,0,0,0,60000]],
  ['当期純利益', [0,0,0,0,180000,0,0,180000]]
];
const worksheetCells = {}; const worksheetInputCells = [];
const worksheetTableRows = worksheetRows.map(([account, values], rowIndex) => {
  const row = { account };
  ['tbDebit','tbCredit','adjDebit','adjCredit','plDebit','plCredit','bsDebit','bsCredit'].forEach((column, columnIndex) => {
    const id = `${column}_${rowIndex + 1}`;
    // 元試算表と意味のないゼロ欄は資料として固定表示し、転記・調整が必要な欄だけを解答させる。
    const assessable = columnIndex >= 2 && values[columnIndex] !== 0;
    row[column] = assessable ? '入力' : (columnIndex < 2 && values[columnIndex] !== 0 ? values[columnIndex] : '—');
    if (assessable) { worksheetInputCells.push(id); worksheetCells[id] = values[columnIndex]; }
  });
  return row;
});
