const SemanticJournalAnswerKey = new Map(Object.values(QuestionData)
  .filter(item => item.type === 'journal')
  .map(item => [item.id, JSON.stringify({ debit:item.answer.debit, credit:item.answer.credit })]));

// 表示数値から偶然作れる値と、そのセルの会計上の正答は同義ではない。
// 起動後の改ざんを検出するため、レビュー済みのセル単位キーを問題データとは別に保持する。
// 会計上の独立性は scripts/audit-data.js の個別不変条件でも重ねて検証する。
const SemanticTableAnswerKey = new Map(Object.values(QuestionData)
  .filter(item => item.type !== 'journal')
  .map(item => [item.id, JSON.stringify(item.answer.cells)]));

// High-risk closing questions use visible accounting facts rather than the authored answer as their oracle.
function parseMonthDay(value) {
  const match=String(value || '').normalize('NFKC').match(/(?:\d{4}[年/.-])?(\d{1,2})[月/.-](\d{1,2})日?/);
  if(!match)return null;
  const month=Number(match[1]),day=Number(match[2]);
  return month>=1&&month<=12&&day>=1&&day<=31?{month,day}:null;
}
// Disposal dates are exclusive; closing dates include the closing month.
function monthDistance(startValue,endValue,{inclusiveEnd=false}={}) {
  const start=parseMonthDay(startValue),end=parseMonthDay(endValue);
  if(!start||!end)return null;
  return (end.month-start.month+12)%12+(inclusiveEnd?1:0);
}
function chronologicalRows(rows,dateKey) {
  return [...rows].map((row,index)=>({row,index,date:parseMonthDay(row[dateKey])})).sort((a,b)=>{
    if(!a.date||!b.date)return a.date?-1:b.date?1:a.index-b.index;
    return a.date.month-b.date.month||a.date.day-b.date.day||a.index-b.index;
  }).map(entry=>entry.row);
}
function independentlyDerivedTableCells(item) {
  const rows=item?.table?.rows || [];
  const numeric=value => typeof value === 'number' ? value : 0;
  if (item?.format === 'bookkeeping-account-rule') {
    const questionText=String(item.question||'');
    const requiredQuestionTerms=['勘定記入法則','資産','負債','増減','貸借平均','借方合計','貸方合計'];
    const requiredRowLabels=[
      '資産の増加を記入する側',
      '資産の減少を記入する側',
      '負債の増加を記入する側',
      '負債の減少を記入する側',
      '貸借平均の原理：借方合計と貸方合計'
    ];
    const rowLabels=rows.map(row=>String(row?.item||''));
    if(!requiredQuestionTerms.every(term=>questionText.includes(term)))return null;
    if(!requiredRowLabels.every(label=>rowLabels.includes(label)))return null;
    return {assetIncreaseSide:'借方',assetDecreaseSide:'貸方',liabilityIncreaseSide:'貸方',liabilityDecreaseSide:'借方',balancePrinciple:'一致'};
  }
  if (item?.format === 'fixed-asset-ledger') {
    if(item.id==='L030'){
      const questionText=String(item.question||''),row=rows[0]||{};
      const normalizeNumber=value=>{
        if(value===null||value===undefined||value==='')return null;
        const normalized=String(value).normalize('NFKC').replace(/,/g,'').trim();
        if(!/^-?\d+(?:\.\d+)?$/u.test(normalized))return null;
        const number=Number(normalized);
        return Number.isFinite(number)?number:null;
      };
      const normalizeMethod=value=>{
        const normalized=String(value??'').normalize('NFKC').trim();
        return normalized==='定額法'||normalized==='定率法'?normalized:null;
      };
      const reconcile=(leftRaw,rightRaw,normalize,equal=(left,right)=>left===right)=>{
        const leftPresent=leftRaw!==null&&leftRaw!==undefined&&leftRaw!=='';
        const rightPresent=rightRaw!==null&&rightRaw!==undefined&&rightRaw!=='';
        if(!leftPresent&&!rightPresent)return {ok:false,value:null};
        const left=leftPresent?normalize(leftRaw):null,right=rightPresent?normalize(rightRaw):null;
        if((leftPresent&&left===null)||(rightPresent&&right===null))return {ok:false,value:null};
        if(leftPresent&&rightPresent&&!equal(left,right))return {ok:false,value:null};
        return {ok:true,value:leftPresent?left:right};
      };
      const questionNumber=label=>questionText.match(new RegExp(`${label}\\s*([0-9０-９,，]+)`,'u'))?.[1]??null;
      const questionAcquisitionText=questionText.match(/([0-9０-９]{1,2}(?:月|[\/.\-])[0-9０-９]{1,2}日?)(?:に)?取得/u)?.[1]||questionText.match(/取得日(?:は|：|:)?\s*([0-9０-９]{1,2}(?:月|[\/.\-])[0-9０-９]{1,2}日?)/u)?.[1]||null;
      const questionMethod=questionText.match(/減価償却方法(?:は)?[^。]*(定額法|定率法)/u)?.[1]||null;
      const acquisition=reconcile(questionAcquisitionText,row.acquisitionDate,parseMonthDay,(left,right)=>left.month===right.month&&left.day===right.day);
      const costEvidence=reconcile(questionNumber('取得原価'),row.acquisitionCost,normalizeNumber);
      const residualEvidence=reconcile(questionNumber('残存価額'),row.residualValue,normalizeNumber);
      const lifeEvidence=reconcile(questionNumber('耐用年数'),row.life,normalizeNumber);
      const methodEvidence=reconcile(questionMethod,row.method,normalizeMethod);
      if(!/会計期間[^。]*4月1日[^。]*3月31日/u.test(questionText))return null;
      if(!acquisition.ok||!costEvidence.ok||!residualEvidence.ok||!lifeEvidence.ok||!methodEvidence.ok)return null;
      const cost=costEvidence.value,residual=residualEvidence.value,life=lifeEvidence.value,method=methodEvidence.value;
      if(method!=='定額法'||residual!==0||!Number.isFinite(cost)||!Number.isFinite(life)||life<=0)return null;
      const annual=(cost-residual)/life;
      if(!Number.isFinite(annual))return null;
      const months=monthDistance(`${acquisition.value.month}/${acquisition.value.day}`,'3/31',{inclusiveEnd:true});
      if(!Number.isInteger(months))return null;
      const depreciation=annual*months/12;
      return {annualDepreciation:annual,months,currentDepreciation:depreciation,closingAccumulated:depreciation,closingBookValue:cost-depreciation};
    }
    const visible=JSON.stringify({question:item.question,materials:item.materials,rows:item.table?.rows});
    const numberAfter=label=>Number(visible.match(new RegExp(`${label}[^0-9]*([0-9,]+)`))?.[1].replace(/,/g,''));
    const method=/定額法/.test(visible), residual=numberAfter('残存価額'), life=numberAfter('耐用年数');
    if(!method||residual!==0||!Number.isFinite(life)||life<=0)return null;
    const cost=numberAfter('取得原価'), annual=(cost-residual)/life;
    if(!Number.isFinite(cost)||!Number.isFinite(annual))return null;
    if(item.id==='L005')return {currentDepreciation:annual,closingBookValue:cost-annual};
    if(item.id==='L010'||item.id==='L020'){
      const opening=numberAfter('期首減価償却累計額'),closing=opening+annual;
      return {currentDepreciation:annual,closingAccumulated:closing,closingBookValue:cost-closing};
    }
    if(item.id==='L015')return {acquisitionDate:String(item.materials?.[0]?.['取得日']),acquisitionCost:cost,currentDepreciation:annual,closingBookValue:cost-annual};
    const acquisition=item.materials?.[0]?.['取得日']||rows[0]?.acquisitionDate||String(item.question).match(/([0-9]{1,2}月[0-9]{1,2}日)/)?.[1];
    if(item.id==='L040'){
      const [a,b]=item.materials||[], costA=Number(a?.['取得原価']),costB=Number(b?.['取得原価']);
      const monthsA=monthDistance(a?.['取得日'],a?.['売却日']),monthsB=monthDistance(b?.['取得日'],b?.['決算日'],{inclusiveEnd:true});
      if(!Number.isInteger(monthsA)||!Number.isInteger(monthsB))return null;
      const annualA=costA/life,annualB=costB/life,depreciationA=annualA*monthsA/12,depreciationB=annualB*monthsB/12,bookA=costA-depreciationA;
      return {annualA,monthsA,depreciationA,bookA,lossA:bookA-Number(a?.['売却価額']),annualB,monthsB,depreciationB,bookB:costB-depreciationB};
    }
    const closing=item.materials?.find(row=>row['決算日'])?.['決算日']||'3/31',months=monthDistance(acquisition,closing,{inclusiveEnd:true});
    if(!Number.isInteger(months))return null;
    const depreciation=annual*months/12, base={months,currentDepreciation:depreciation,closingBookValue:cost-depreciation};
    if(item.id==='L025')return base;
    if(item.id==='L033')return {acquisitionDate:String(acquisition),acquisitionCost:cost,months,currentDepreciation:depreciation,closingAccumulated:depreciation,closingBookValue:cost-depreciation};
  }
  // A running ledger is derived exclusively from its opening balance and postings.
  if (item?.type === 'ledger' && item.table?.inputCells?.join(',') === 'r2_balance,r3_balance' && rows.length === 3) {
    let balance=Number(rows[0].balance);
    const cells={};
    const liability=Number.isFinite(rows[0].credit)&&!Number.isFinite(rows[0].debit);
    rows.slice(1).forEach((posting,index) => { balance += (liability?-1:1)*(numeric(posting.debit)-numeric(posting.credit)); cells[`r${index+2}_balance`]=balance; });
    return cells;
  }
  if (item?.type === 'ledger' && item.table?.inputCells?.join(',') === 'r1_currentDepreciation,r1_closingBookValue') {
    const asset=rows[0] || {}, depreciation=Number(asset.acquisitionCost)/Number(asset.life);
    return {r1_currentDepreciation:depreciation,r1_closingBookValue:Number(asset.acquisitionCost)-Number(asset.openingAccumulated)-depreciation};
  }
  if (item?.id === 'L033') {
    const row=item.materials?.[0]||{}, life=Number(String(item.question).match(/耐用年数([0-9]+)年/)?.[1]), months=Number(String(item.question).match(/使用期間は([0-9]+)か月/)?.[1]);
    const cost=Number(row.取得原価), depreciation=cost/life*months/12;
    return {date:String(row.取得日),cost,depreciation,bookValue:cost-depreciation};
  }
  if (item?.id === 'F001') {
    const amount = category => (item.materials || []).filter(row => row['区分'] === category).reduce((sum, row) => sum + Number(row['金額'] || 0), 0);
    const sales=amount('収益'), costOfSales=amount('売上原価'), expenses=amount('費用');
    return { sales, costOfSales, expenses, netIncome:sales-costOfSales-expenses };
  }
  if (item?.id === 'D019') {
    const rows=Object.fromEntries((item.materials || []).map(row => [row['勘定科目'], row]));
    const debit = account => Number(rows[account]?.['整理前借方'] || 0);
    const credit = account => Number(rows[account]?.['整理前貸方'] || 0);
    const adjustment = account => Number(String(rows[account]?.['整理事項'] || '').match(/[0-9,]+/)?.[0].replace(/,/g, '') || 0);
    const prepaid=adjustment('前払保険料'), depreciation=adjustment('減価償却費');
    const cells={cash:debit('現金'),receivables:debit('売掛金'),insurance:debit('保険料')-prepaid,prepaid,equipment:debit('備品'),depreciation,payables:credit('買掛金'),accumulated:adjustment('減価償却累計額'),capital:credit('資本金'),retained:credit('繰越利益剰余金'),sales:credit('売上')};
    cells.debitTotal=cells.cash+cells.receivables+cells.insurance+cells.prepaid+cells.equipment+cells.depreciation;
    cells.creditTotal=cells.payables+cells.accumulated+cells.capital+cells.retained+cells.sales;
    return cells;
  }
  // 決算整理の計算問題は、問題文に示された基礎額・割合・耐用年数から導く。
  if (item?.id === 'D020') {
    const text=String(item.question || '');
    if (/損益勘定/.test(text)) {
      const value=label=>Number(text.match(new RegExp(`${label}([0-9,]+)円`))?.[1].replace(/,/g,''));
      const sales=value('売上'), purchases=value('仕入'), insurance=value('保険料'), depreciation=value('減価償却費');
      return {sales,purchases,insurance,depreciation,profit:sales-purchases-insurance-depreciation};
    }
    const insurance=Number(text.match(/保険料([0-9,]+)円/)?.[1].replace(/,/g,''));
    const fraction=Number(text.match(/([0-9]+)分の1が次期分/)?.[1]);
    const equipment=Number(text.match(/備品([0-9,]+)円/)?.[1].replace(/,/g,''));
    const life=Number(text.match(/耐用年数([0-9]+)年/)?.[1]);
    const insuranceAdjustment=insurance/fraction, depreciation=equipment/life;
    return {insurance_adjustment:insuranceAdjustment,insurance_expense_after:insurance-insuranceAdjustment,depreciation_expense:depreciation,equipment_book_value_after:equipment-depreciation};
  }
  // 帳簿の固定行を取引事実として、FIFO、定額法、残高集計を再実行する。
  if (item?.category === '商品有高帳' && /先入先出法/.test(item.question || '')) {
    const rows=item.table?.rows || [], opening=rows[0], purchase=rows[1], issue=rows[2];
    const issued=Math.min(Number(issue?.quantity), Number(opening?.quantity));
    const issueAmount=issued*Number(opening?.unitPrice);
    const balanceAmount=(Number(opening?.quantity)-issued)*Number(opening?.unitPrice)+Number(purchase?.quantity)*Number(purchase?.unitPrice);
    return {r3_unitPrice:Number(opening?.unitPrice),r3_amount:issueAmount,r4_amount:balanceAmount};
  }
  if (String(item?.category || '').startsWith('固定資産台帳') && /定額法/.test(item.question || '')) {
    if (item.id === 'L040' && item.materials?.length === 2) {
      const [a,b]=item.materials, life=Number(String(item.question).match(/耐用年数([0-9]+)年/)?.[1]);
      const monthsA=monthDistance(a.取得日,a.売却日),monthsB=monthDistance(b.取得日,'3/31',{inclusiveEnd:true});
      if(!Number.isInteger(monthsA)||!Number.isInteger(monthsB)||!Number.isFinite(life)||life<=0)return null;
      const annualA=Number(a.取得原価)/life, depreciationA=annualA*monthsA/12, bookA=Number(a.取得原価)-depreciationA;
      const depreciationB=Number(b.取得原価)/life*monthsB/12;
      return {annualA,depreciationA,bookA,lossA:bookA-Number(a.売却価額),depreciationB,bookB:Number(b.取得原価)-depreciationB};
    }
    const row=item.table?.rows?.[0] || {}, depreciation=Number(row.acquisitionCost)/Number(row.life);
    return {r1_currentDepreciation:depreciation,r1_closingBookValue:Number(row.acquisitionCost)-Number(row.openingAccumulated)-depreciation};
  }
  if (item?.type === 'trial_balance' && item.table?.inputCells?.join(',') === 'total_debit,total_credit') {
    const rows=(item.table.rows || []).filter(row => row.account !== '合計');
    return {total_debit:rows.reduce((sum,row)=>sum+Number(row.debit || 0),0),total_credit:rows.reduce((sum,row)=>sum+Number(row.credit || 0),0)};
  }
  if (item?.id === 'L039') {
    const text=String(item.question || ''), principal=Number(text.match(/借入金([0-9,]+)円/)?.[1].replace(/,/g,'')), rate=Number(text.match(/年利率([0-9.]+)%/)?.[1])/100;
    const annualPayment=principal*rate, accrual=annualPayment/2;
    return {priorAccrual:accrual,reversal:accrual,annualPayment,currentAccrual:accrual,profitTransfer:annualPayment,nextBalance:0};
  }
  if (item?.id === 'L044') {
    const income=Number(item.materials?.[0]?.収入 || 0), expense=Number(item.materials?.[1]?.支出 || 0);
    return {value1:income,value2:expense,value3:income-expense};
  }
  if (item?.type === 'ledger' && item.materials?.length && item.table?.inputCells?.includes('d1Account')) {
    const folios=Object.fromEntries([...String(item.question).matchAll(/(現金|売掛金|売上|通信費)([0-9]+)/g)].map(m=>[m[1],Number(m[2])]));
    const entries=item.materials.map(source=>{
      const text=String(source.取引||source.内容||''), amount=Number(text.match(/([0-9,]+)円/)?.[1].replace(/,/g,''));
      if(/掛販売/.test(text))return {d:'売掛金',c:'売上',amount};
      if(/現金販売/.test(text))return {d:'現金',c:'売上',amount};
      if(/掛仕入/.test(text))return {d:'仕入',c:'買掛金',amount};
      if(/現金仕入/.test(text))return {d:'仕入',c:'現金',amount};
      if(/通信費.+現金(?:払い|で支払)/.test(text))return {d:'通信費',c:'現金',amount};
      return null;
    });
    if(entries.some(entry=>!entry||!Number.isFinite(entry.amount)))return null;
    return {date1:item.materials[0].日付,d1Account:entries[0].d,d1Ref:folios[entries[0].d],d1Amount:entries[0].amount,c1Account:entries[0].c,c1Ref:folios[entries[0].c],c1Amount:entries[0].amount,date2:item.materials[1].日付,d2Account:entries[1].d,d2Ref:folios[entries[1].d],d2Amount:entries[1].amount,c2Account:entries[1].c,c2Ref:folios[entries[1].c],c2Amount:entries[1].amount};
  }
  if (item?.type === 'ledger' && item.materials?.length && item.table?.inputCells?.includes('date1')) {
    const folios=Object.fromEntries([...String(item.question).matchAll(/(現金|売掛金|売上|通信費)([0-9]+)/g)].map(match=>[match[1],match[2]]));
    const entries=item.materials.map(source=>{
      const text=String(source.内容||''), amount=Number(text.match(/([0-9,]+)円/)?.[1].replace(/,/g,''));
      if(/掛販売/.test(text))return {debit:'売掛金',credit:'売上',summary:'掛売上',amount};
      if(/現金販売/.test(text))return {debit:'現金',credit:'売上',summary:'現金売上',amount};
      if(/通信費.+現金(?:払い|で支払)/.test(text))return {debit:'通信費',credit:'現金',summary:'通信費現金払い',amount};
      return null;
    });
    if(entries.some(entry=>!entry||!Number.isFinite(entry.amount)))return null;
    const first=entries[0], total=entries.reduce((sum,entry)=>sum+entry.amount,0);
    return {date1:item.materials[0].日付,summary1:first.summary,folio1:`${folios[first.debit]}・${folios[first.credit]}`,debitTotal:total,creditTotal:total};
  }
  if (item?.type === 'ledger' && item.materials?.length && item.table?.inputCells?.includes('received')) {
    const notes=chronologicalRows(item.materials.filter(row=>row.種類==='約束手形受取'),'日付'),due=chronologicalRows(notes,'満期日'); return {received:notes[0].日付,due:due.at(-1).満期日,drawer:notes.map(row=>row.振出人).join('・'),total:notes.reduce((sum,row)=>sum+row.金額,0)};
  }
  if (item?.type === 'ledger' && item.materials?.length && item.table?.inputCells?.includes('issued')) {
    const notes=chronologicalRows(item.materials.filter(row=>row.種類==='約束手形振出'),'日付'),due=chronologicalRows(notes,'満期日'); return {issued:notes[0].日付,due:due.at(-1).満期日,payee:notes.map(row=>row.受取人).join('・'),total:notes.reduce((sum,row)=>sum+row.金額,0)};
  }
  if (item?.type === 'ledger' && item.materials?.length && item.table?.inputCells?.includes('side')) {
    const opening=Number(String(item.question).match(/期首残高([0-9,]+)円/)?.[1].replace(/,/g,'')), last=item.materials.at(-1);
    const side=Number.isFinite(Number(last.借方))?'借方':Number.isFinite(Number(last.貸方))?'貸方':null;
    if(!side)return null;
    return {date:last.日付,counterpart:last.相手勘定,side,balance:item.materials.reduce((sum,row)=>sum+numeric(row.借方)-numeric(row.貸方),opening)};
  }
  if (item?.type === 'ledger' && item.materials?.length && item.table?.inputCells?.includes('balanceSide')) {
    const opening=Number(String(item.question).match(/期首貸方残高([0-9,]+)円/)?.[1].replace(/,/g,'')), last=item.materials.at(-1);
    const signedBalance=item.materials.reduce((sum,row)=>sum+numeric(row.増加)-numeric(row.減少),opening);
    return {date:last.日付,counterpart:last.相手勘定,balanceSide:signedBalance<0?'借方':'貸方',balance:Math.abs(signedBalance)};
  }
  if (item?.type === 'ledger' && item.materials?.length && item.table?.inputCells?.includes('received1')) {
    const cells={};item.materials.forEach((row,i)=>{const n=i+1;Object.assign(cells,{[`received${n}`]:row.受取日,[`drawer${n}`]:row.振出人,[`drawn${n}`]:row.振出日,[`due${n}`]:row.満期日,[`bank${n}`]:row.支払場所,[`description${n}`]:row.摘要,[`amount${n}`]:row.金額});});cells.total=item.materials.reduce((s,r)=>s+r.金額,0);return cells;
  }
  if (item?.type === 'ledger' && item.materials?.length && item.table?.inputCells?.includes('drawn1')) {
    const cells={};item.materials.forEach((row,i)=>{const n=i+1;Object.assign(cells,{[`drawn${n}`]:row.振出日,[`payee${n}`]:row.受取人,[`due${n}`]:row.満期日,[`bank${n}`]:row.支払場所,[`description${n}`]:row.摘要,[`amount${n}`]:row.金額});});cells.total=item.materials.reduce((s,r)=>s+r.金額,0);return cells;
  }
  if (item?.type === 'ledger' && item.table?.inputCells?.join(',') === 'value1,value2,value3') {
    const text=String(item.question), amounts=[...text.matchAll(/([0-9,]+)円/g)].map(m=>Number(m[1].replace(/,/g,'')));
    if (item.materials?.length) { const values=item.materials.map(row=>Number(row.預入!=null&&row.預入!=='—'?row.預入:row.引出!=null&&row.引出!=='—'?row.引出:row.金額)); if(values.every(Number.isFinite)&&values.length===2)return {value1:values[0],value2:values[1],value3:values[0]+(/引出/.test(JSON.stringify(item.materials))?-values[1]:values[1])}; }
    if (/移動平均法/.test(text)){const n=[...text.matchAll(/([0-9,]+)個@([0-9,]+)円/g)].map(m=>[Number(m[1].replace(/,/g,'')),Number(m[2].replace(/,/g,''))]),issued=Number(text.match(/([0-9,]+)個を払い出/)?.[1].replace(/,/g,''));const average=n.reduce((s,x)=>s+x[0]*x[1],0)/n.reduce((s,x)=>s+x[0],0);return {value1:average,value2:average*issued,value3:average*(n.reduce((s,x)=>s+x[0],0)-issued)};}
    if(amounts.length>=2)return {value1:amounts[0],value2:amounts[1],value3:/伝票/.test(text)?amounts[2]:amounts[0]-amounts[1]};
  }
  // Correction = correct transaction entry minus the entry actually recorded.
  if (item?.type === 'correction' && item.materials?.length === 1) {
    const {recorded='',evidence=''}=item.materials[0], parse=side=>{const m=String(recorded).match(new RegExp(`（${side}）([^ ]+) ([0-9,]+)`));return m&&{account:m[1],amount:Number(m[2].replace(/,/g,''))};};
    const rd=parse('借'),rc=parse('貸'), amount=Number(String(evidence).match(/([0-9,]+)円/)?.[1].replace(/,/g,''));
    let correct;
    if(/買掛金/.test(evidence)&&/(支払|振り込)/.test(evidence))correct={d:'買掛金',c:'普通預金'};else if(/事務用品/.test(evidence))correct={d:'消耗品費',c:'現金'};else if(/売掛金.+回収/.test(evidence))correct={d:/現金で/.test(evidence)?'現金':'普通預金',c:'売掛金'};else if(/複合機|業務用パソコン/.test(evidence))correct={d:'備品',c:'未払金'};else if(/掛けで販売/.test(evidence))correct={d:'売掛金',c:'売上'};else if(/貸付金利息/.test(evidence))correct={d:'普通預金',c:'受取利息'};else if(/通信費/.test(evidence))correct={d:'通信費',c:'現金'};else if(/借入金元本/.test(evidence))correct={d:'借入金',c:'普通預金'};else if(/火災保険料/.test(evidence))correct={d:'保険料',c:'普通預金'};else if(/引渡前.+内金/.test(evidence))correct={d:'現金',c:'前受金'};else if(/商品受領前.+内金/.test(evidence))correct={d:'前払金',c:'普通預金'};else if(/概算前渡し/.test(evidence))correct={d:'仮払金',c:'現金'};else if(/立替払い/.test(evidence))correct={d:'立替金',c:'現金'};else if(/収入印紙/.test(evidence))correct={d:'租税公課',c:'現金'};else if(/振込手数料/.test(evidence))correct={d:'支払手数料',c:'普通預金'};else if(/給与総額/.test(evidence))correct={d:'給料',c:'普通預金'};
    if(correct){const deltas=new Map();const add=(a,v)=>deltas.set(a,(deltas.get(a)||0)+v);add(correct.d,amount);add(correct.c,-amount);add(rd.account,-rd.amount);add(rc.account,rc.amount);const debit=[...deltas].find(([,v])=>v>0),credit=[...deltas].find(([,v])=>v<0);return {debitAccount:debit[0],debitAmount:debit[1],creditAccount:credit[0],creditAmount:-credit[1]};}
  }
  if (item?.type === 'worksheet' && /保険料.+分の1が次期分/.test(item.question||'')) {
    const text=item.question, insurance=Number(text.match(/保険料([0-9,]+)円/)?.[1].replace(/,/g,'')), divisor=Number(text.match(/([0-9]+)分の1/)?.[1]), equipment=Number(text.match(/備品([0-9,]+)円/)?.[1].replace(/,/g,'')), life=Number(text.match(/耐用年数([0-9]+)年/)?.[1]);const adjustment=insurance/divisor,depreciation=equipment/life;return {insurance_adjustment:adjustment,insurance_expense_after:insurance-adjustment,depreciation_expense:depreciation,equipment_book_value_after:equipment-depreciation};
  }
  if (item?.type === 'worksheet' && item.format === 'eight-column-worksheet' && rows.length) {
    const cells={};rows.slice(0,6).forEach((r,i)=>{if(Number.isFinite(r.tbDebit))cells[`bsDebit_${i+1}`]=r.tbDebit;if(Number.isFinite(r.tbCredit))cells[`bsCredit_${i+1}`]=r.tbCredit;});const adjustmentText=Array.isArray(item.adjustments)?item.adjustments.join(' '):String(item.question||'');const [prepaid,depreciation]=[...adjustmentText.matchAll(/([0-9,]+)円/g)].map(m=>+m[1].replace(/,/g,'')), profit=rows[6].tbCredit-rows[7].tbDebit-(rows[8].tbDebit-prepaid)-depreciation;Object.assign(cells,{plCredit_7:rows[6].tbCredit,plDebit_8:rows[7].tbDebit,adjCredit_9:prepaid,plDebit_9:rows[8].tbDebit-prepaid,adjDebit_10:prepaid,bsDebit_10:prepaid,adjDebit_11:depreciation,plDebit_11:depreciation,adjCredit_12:depreciation,bsCredit_12:depreciation,plDebit_13:profit,bsCredit_13:profit});return cells;
  }
  if (item?.type === 'financial_statement' && rows.length) {const sum=section=>rows.filter(r=>r.section===section&&Number.isFinite(r.amount)).reduce((s,r)=>s+r.amount,0),assets=sum('資産'),liabilities=sum('負債'),capital=rows.find(r=>r.account==='資本金')?.amount||0;return {retainedEarnings:assets-liabilities-capital,assetsTotal:assets,liabilitiesEquityTotal:assets};}
  if (item?.type === 'comprehensive' && item.format !== 'exam-question-3' && item.materials?.length) {
    let cash=0,revenue=0,expense=0;for(const row of item.materials){const text=String(row.transaction),amount=Number(text.match(/([0-9,]+)円/)?.[1]?.replace(/,/g,'')||0);if(/現金残高/.test(text)){cash=amount;continue;}if(/借り入れ.+現金/.test(text)||/内金.+現金で受け取/.test(text))cash+=amount;if(/現金で購入|現金で.+仕入|現金払い|現金で支払|現金で前払い/.test(text))cash-=amount;if(/現金で.+販売/.test(text)){cash+=amount;revenue+=amount;}if(/掛けで販売/.test(text))revenue+=amount;if(/商品を現金で.+仕入/.test(text))expense+=amount;if(/通信費/.test(text))expense+=amount;if(/給料.+未払い|減価償却費/.test(text))expense+=amount;}return {endingCash:cash,profit:revenue-expense};
  }
  if (item?.type === 'correction' && item.materials?.length === 1) {
    const {recorded='',evidence=''}=item.materials[0];
    const wrongDebit=String(recorded).match(/（借）([^ ]+) ([0-9,]+)/);
    const evidenceMatch=String(evidence).match(/([^0-9]+?)([0-9,]+)円/);
    if (wrongDebit && evidenceMatch && /広告掲載料/.test(evidence)) {
      const amount=Number(evidenceMatch[2].replace(/,/g,''));
      return {debitAccount:'広告宣伝費',debitAmount:amount,creditAccount:wrongDebit[1],creditAmount:amount};
    }
  }
  return null;
}

// 仕訳も authored answer ではなく、表示された取引事実と勘定規則から導く。
function independentlyDerivedJournal(item) {
  const text=String(item?.question || '');
  const numbers=[...text.matchAll(/([0-9][0-9,]*(?:\.[0-9]+)?)\s*(％|%|円|年)?/g)].map(match=>({value:Number(match[1].replace(/,/g,'')),unit:match[2]||''}));
  const yen=numbers.filter(number=>number.unit==='円').map(number=>number.value);
  const amount=(index=0)=>yen[index];
  const entry=(debit,credit)=>({debit,credit});
  const row=(account,value)=>({account,amount:value});
  if (/繰越利益剰余金.+現金配当.+決議/.test(text) && /追加積立は不要/.test(text)) {
    return entry([row('繰越利益剰余金',amount())],[row('未払配当金',amount())]);
  }
  // Normalize synonymous surface forms before applying double-entry rules.
  const transactionType = /追加出資|追加払込み|株主から.+払込み|増資として.+払/.test(text) ? 'capital_contribution'
    : /販売用商品.+翌月払い|商品.+仕入れ?.+代金.+(?:後日|翌月).*(?:支払|掛け)/.test(text) ? 'credit_purchase'
    : /商品.+(?:納品|販売).+(?:翌月回収|後日.+受け取).+掛け/.test(text) ? 'credit_sale' : null;
  if (transactionType==='capital_contribution') return entry([row('現金',amount())],[row('資本金',amount())]);
  if (transactionType==='credit_purchase') return entry([row('仕入',amount())],[row('買掛金',amount())]);
  if (transactionType==='credit_sale') return entry([row('売掛金',amount())],[row('売上',amount())]);
  if (/手許現金.+普通預金.+預け入れ/.test(text)) return entry([row('普通預金',amount())],[row('現金',amount())]);
  if (/当座預金口座を開設/.test(text)) return entry([row('当座預金',amount())],[row('普通預金',amount())]);
  if (/商品.+仕入れ、代金は掛け/.test(text) && !/運賃/.test(text)) return entry([row('仕入',amount())],[row('買掛金',amount())]);
  if (/商品.+販売し、代金は掛け/.test(text) && !/運賃/.test(text)) return entry([row('売掛金',amount())],[row('売上',amount())]);
  if (/仕入れ.+引取運賃/.test(text)) return entry([row('仕入',amount(0)+amount(1))],[row('買掛金',amount(0)),row('現金',amount(1))]);
  if (/販売し.+発送運賃/.test(text)) return entry([row('売掛金',amount(0)),row('発送費',amount(1))],[row('売上',amount(0)),row('現金',amount(1))]);
  if (/掛けで仕入れた商品.+返品/.test(text)) return entry([row('買掛金',amount())],[row('仕入',amount())]);
  if (/掛けで販売した商品.+返品/.test(text)) return entry([row('売上',amount())],[row('売掛金',amount())]);
  if (/売掛金.+普通預金.+振り込まれ/.test(text)) return entry([row('普通預金',amount())],[row('売掛金',amount())]);
  if (/買掛金.+普通預金.+振り込んだ/.test(text)) return entry([row('買掛金',amount())],[row('普通預金',amount())]);
  if (/買掛金.+電子記録債務/.test(text)) return entry([row('買掛金',amount())],[row('電子記録債務',amount())]);
  if (/売掛金.+電子記録債権/.test(text)) return entry([row('電子記録債権',amount())],[row('売掛金',amount())]);
  if (/クレジットカードで販売/.test(text)) {const sale=amount(),rate=(numbers.find(number=>number.unit==='％'||number.unit==='%')?.value||0)/100,fee=sale*rate;return entry([row('クレジット売掛金',sale-fee),row('支払手数料',fee)],[row('売上',sale)]);}
  if (/商品受領前の内金/.test(text)) return entry([row('前払金',amount())],[row('現金',amount())]);
  if (/商品引渡前の内金/.test(text)) return entry([row('現金',amount())],[row('前受金',amount())]);
  if (/現金実査額が帳簿残高より/.test(text)) return entry([row('現金過不足',amount())],[row('現金',amount())]);
  if (/現金不足額.+通信費/.test(text)) return entry([row('通信費',amount())],[row('現金過不足',amount())]);
  if (/小口現金係.+定額資金/.test(text)) return entry([row('小口現金',amount())],[row('当座預金',amount())]);
  if (/小口現金係.+交通費/.test(text)) {const total=amount(0)+amount(1)+amount(2);return entry([row('旅費交通費',amount(0)),row('通信費',amount(1)),row('消耗品費',amount(2))],[row('当座預金',total)]);}
  if (/業務用パソコン/.test(text)) return entry([row('備品',amount())],[row('未払金',amount())]);
  if (/取得原価.+減価償却累計額.+備品を.+売却/.test(text)) {const [cost,accumulated,proceeds]=yen,gain=proceeds-(cost-accumulated),settlement=/翌月受け取る/.test(text)?'未収入金':'普通預金';return entry([row(settlement,proceeds),row('減価償却累計額',accumulated),...(gain<0?[row('固定資産売却損',-gain)]:[])],[row('備品',cost),...(gain>0?[row('固定資産売却益',gain)]:[])]);}
  if (/出張旅費の概算額/.test(text)) return entry([row('仮払金',amount())],[row('現金',amount())]);
  if (/出張から戻り.+未使用の現金/.test(text)) return entry([row('旅費交通費',amount(0)),row('現金',amount(1))],[row('仮払金',amount(0)+amount(1))]);
  if (/会社が現金で立て替え/.test(text)) return entry([row('立替金',amount())],[row('現金',amount())]);
  if (/銀行から.+借り入れ/.test(text)) return entry([row('普通預金',amount())],[row('借入金',amount())]);
  if (/借入金元本.+利息/.test(text)) return entry([row('借入金',amount(0)),row('支払利息',amount(1))],[row('普通預金',amount(0)+amount(1))]);
  if (/給与総額.+所得税預り金.+社会保険料預り金/.test(text)) return entry([row('給料',amount(0))],[row('所得税預り金',amount(1)),row('社会保険料預り金',amount(2)),row('普通預金',amount(0)-amount(1)-amount(2))]);
  if (/所得税.+税務署へ納付/.test(text)) return entry([row('所得税預り金',amount())],[row('普通預金',amount())]);
  if (/社会保険料.+従業員預り分.+会社負担分/.test(text)) return entry([row('社会保険料預り金',amount(0)),row('法定福利費',amount(1))],[row('普通預金',amount(0)+amount(1))]);
  if (/固定資産税/.test(text)) return entry([row('租税公課',amount())],[row('現金',amount())]);
  if (/収入印紙.+購入し、直ちに使用/.test(text)) return entry([row('租税公課',amount())],[row('現金',amount())]);
  if (/取引先へ.+貸し付け/.test(text)) return entry([row('貸付金',amount())],[row('普通預金',amount())]);
  if (/貸付金の利息.+入金/.test(text)) return entry([row('普通預金',amount())],[row('受取利息',amount())]);
  if (/収入印紙.+未使用/.test(text)) return entry([row('貯蔵品',amount())],[row('租税公課',amount())]);
  if (/他店発行の商品券/.test(text)) return entry([row('受取商品券',amount())],[row('売上',amount())]);
  if (/返還される敷金/.test(text)) return entry([row('差入保証金',amount())],[row('普通預金',amount())]);
  if (/消耗品費.+誤って通信費/.test(text)) return entry([row('消耗品費',amount())],[row('通信費',amount())]);
  if (/買掛金.+借方・貸方とも/.test(text)) {const difference=amount(0)-amount(1);return entry([row('買掛金',difference)],[row('普通預金',difference)]);}
  if (/掛売上が未記帳/.test(text)) return entry([row('売掛金',amount())],[row('売上',amount())]);
  if (/保険料.+次期分.+繰り延べ/.test(text)) return entry([row('前払保険料',amount(1))],[row('保険料',amount(1))]);
  if (/借入金利息.+未払い/.test(text)) return entry([row('支払利息',amount())],[row('未払利息',amount())]);
  if (/家賃.+次期分.+繰り延べ/.test(text)) return entry([row('受取家賃',amount(1))],[row('前受家賃',amount(1))]);
  if (/貸付金.+利息.+未収/.test(text)) return entry([row('未収利息',amount())],[row('受取利息',amount())]);
  if (/売掛金残高.+貸倒れを見積もる/.test(text)) {const receivables=amount(0),rate=(numbers.find(number=>number.unit==='％'||number.unit==='%')?.value||0)/100,opening=amount(1),expense=receivables*rate-opening;return entry([row('貸倒引当金繰入',expense)],[row('貸倒引当金',expense)]);}
  if (/前期に発生した売掛金.+回収不能/.test(text)) return entry([row('貸倒引当金',amount())],[row('売掛金',amount())]);
  if (/備品（取得原価.+耐用年数.+定額法/.test(text)) {const cost=amount(),life=numbers.find(number=>number.unit==='年')?.value,depreciation=cost/life;return entry([row('減価償却費',depreciation)],[row('減価償却累計額',depreciation)]);}
  if (/期首商品棚卸高.+期末商品棚卸高/.test(text)) return entry([row('仕入',amount(0)),row('繰越商品',amount(1))],[row('繰越商品',amount(0)),row('仕入',amount(1))]);
  if (/仮払消費税.+仮受消費税.+相殺/.test(text)) {const payable=amount(1)-amount(0);return entry([row('仮受消費税',amount(1))],[row('仮払消費税',amount(0)),row('未払消費税',payable)]);}
  if (/損益勘定の貸方残高/.test(text)) return entry([row('損益',amount())],[row('繰越利益剰余金',amount())]);
  if (/入金.+内容が不明.+仮受金/.test(text)) return entry([row('普通預金',amount())],[row('仮受金',amount())]);
  if (/当座預金を開設/.test(text)) return entry([row('当座預金',amount())],[row('普通預金',amount())]);
  if (/買掛金.+普通預金口座から.+支払/.test(text)) return entry([row('買掛金',amount())],[row('普通預金',amount())]);
  if (/クレジットカード販売/.test(text)){const sale=amount(),rate=(numbers.find(n=>n.unit==='％'||n.unit==='%')?.value||0)/100,fee=sale*rate;return entry([row('クレジット売掛金',sale-fee),row('支払手数料',fee)],[row('売上',sale)]);}
  if (/引渡前の内金.+現金で受け取/.test(text)) return entry([row('現金',amount())],[row('前受金',amount())]);
  if (/実際有高.+帳簿残高より.+少な/.test(text)) return entry([row('現金過不足',amount())],[row('現金',amount())]);
  if (/現金過不足.+通信費の記帳漏れ/.test(text)) return entry([row('通信費',amount())],[row('現金過不足',amount())]);
  if (/小口現金.+定額資金前渡法/.test(text)) return entry([row('小口現金',amount())],[row('当座預金',amount())]);
  if (/長期使用する業務用.+翌月払い/.test(text)) return entry([row('備品',amount())],[row('未払金',amount())]);
  if (/旅費の概算額.+前渡し/.test(text)) return entry([row('仮払金',amount())],[row('現金',amount())]);
  if (/出張精算で旅費.+未使用現金/.test(text)) return entry([row('旅費交通費',amount(0)),row('現金',amount(1))],[row('仮払金',amount(2))]);
  if (/会社がいったん現金で立替払い/.test(text)) return entry([row('立替金',amount())],[row('現金',amount())]);
  if (/借入金の元本.+当期利息/.test(text)) return entry([row('借入金',amount(0)),row('支払利息',amount(1))],[row('普通預金',amount(0)+amount(1))]);
  if (/給与総額.+所得税.+社会保険料.+差引支給額/.test(text)) return entry([row('給料',amount(0))],[row('所得税預り金',amount(1)),row('社会保険料預り金',amount(2)),row('普通預金',amount(3))]);
  if (/社会保険料.+預り分.+会社負担分/.test(text)) return entry([row('社会保険料預り金',amount(0)),row('法定福利費',amount(1))],[row('普通預金',amount(2))]);
  if (/電気料金.+普通預金口座から引き落と/.test(text)) return entry([row('水道光熱費',amount())],[row('普通預金',amount())]);
  if (/収入印紙.+その場で使用/.test(text)) return entry([row('租税公課',amount())],[row('現金',amount())]);
  if (/短期資金.+貸し付け.+普通預金/.test(text)) return entry([row('貸付金',amount())],[row('普通預金',amount())]);
  if (/前期に全額を貸倒処理.+現金で回収/.test(text)) return entry([row('現金',amount())],[row('償却債権取立益',amount())]);
  if (/法人税、住民税及び事業税.+当期負担額/.test(text)) return entry([row('法人税、住民税及び事業税',amount())],[row('未払法人税等',amount())]);
  if (/次期分.+前払保険料/.test(text)) return entry([row('前払保険料',amount(1))],[row('保険料',amount(1))]);
  if (/借入金利息.+まだ支払われていない/.test(text)) return entry([row('支払利息',amount())],[row('未払利息',amount())]);
  if (/次期分.+前受家賃/.test(text)) return entry([row('受取家賃',amount(1))],[row('前受家賃',amount(1))]);
  if (/貸付金利息.+発生済みで未収/.test(text)) return entry([row('未収利息',amount())],[row('受取利息',amount())]);
  if (/当座借越契約.+期中.+仕入代金.+小切手/.test(text)){const purchase=amount(1);return entry([row('仕入',purchase)],[row('当座預金',purchase)]);}
  if (/商品.+売り上げ.+約束手形を受け取/.test(text)) return entry([row('受取手形',amount())],[row('売上',amount())]);
  if (/商品.+仕入れ.+約束手形を振り出/.test(text)) return entry([row('仕入',amount())],[row('支払手形',amount())]);
  if (/受取手形.+満期.+支払手形.+満期/.test(text)) return entry([row('当座預金',amount(0)),row('支払手形',amount(1))],[row('受取手形',amount(0)),row('当座預金',amount(1))]);
  return null;
}

// 第3問はanswerをoracleにせず、表示資料から会計規則で再計算する。
function journalEffectsForEvent(event) {
  if (!event || event.type !== 'unrecordedCashSale' || event.taxMethod !== 'exclusive') return null;
  const netAmount=Number(event.netAmount), taxRate=Number(event.taxRate);
  if (!Number.isFinite(netAmount) || netAmount < 0 || !Number.isFinite(taxRate) || taxRate < 0) return null;
  const taxAmount=Math.round(netAmount*taxRate), cashReceipt=netAmount+taxAmount;
  return Object.freeze({ debit:Object.freeze([{account:'現金',amount:cashReceipt}]), credit:Object.freeze([{account:'売上',amount:netAmount},{account:'仮受消費税',amount:taxAmount}]), netAmount, taxAmount, cashReceipt });
}
function deriveExamQuestion3Expected(item) {
  if (item?.format !== 'exam-question-3') return { valid:false, errors:['第3問形式ではありません'], derivedCells:null };
  const text = JSON.stringify({question:item.question, materials:item.materials}); const errors=[]; let derivedCells=null; let trialBalance=null; let statements=null;
  const material = type => item.materials?.find(row => row.資料区分 === type);
  const numberAfter = (source, label) => {
    const match = String(source || '').match(new RegExp(`${label}[^0-9]*([0-9,]+)`));
    return match ? Number(match[1].replace(/,/g,'')) : Number.NaN;
  };
  if (/統合決算A/.test(item.category)) {
    const balanceRow=item.materials?.find(row => row.資料区分==='整理前残高試算表');
    const adjustments=String(item.materials?.find(row => row.資料区分==='決算整理事項')?.内容 || '');
    const amounts = source => Object.fromEntries([...String(source || '').matchAll(/([^、]+?)([0-9,]+)(?=、|$)/g)].map(match => [match[1].trim(),Number(match[2].replace(/,/g,''))]));
    const debitBalances=amounts(balanceRow?.借方), creditBalances=amounts(balanceRow?.貸方);
    const adjustmentAmount = label => { const match=adjustments.match(new RegExp(`${label}([0-9,]+)円`)); return match ? Number(match[1].replace(/,/g,'')) : Number.NaN; };
    const debit=Object.values(debitBalances).reduce((sum,value)=>sum+value,0), credit=Object.values(creditBalances).reduce((sum,value)=>sum+value,0); trialBalance={debit,credit};
    if (debit!==Number(balanceRow?.借方合計) || credit!==Number(balanceRow?.貸方合計)) errors.push('表示された試算表明細と合計が一致しません');
    const unrecordedSales=adjustmentAmount('未処理の掛売上'), unrecordedPurchases=adjustmentAmount('未処理の掛仕入'), endingInventory=adjustmentAmount('期末商品');
    const depreciation=adjustmentAmount('備品の減価償却'), accruedWages=adjustmentAmount('未払給料'), tax=adjustmentAmount('法人税等');
    const sales=creditBalances.売上+unrecordedSales, receivables=debitBalances.売掛金+unrecordedSales, purchases=debitBalances.仕入+unrecordedPurchases, cost=debitBalances.繰越商品+purchases-endingInventory;
    const allowanceRate=numberAfter(adjustments,'売掛金期末残高の')/100;
    const insuranceStart=Number(adjustments.match(/([0-9]+)月1日に1年分を払った保険料/)?.[1]);
    const closingMonth=Number(String(item.materials?.find(row => /会計期間|決算日/.test(row.資料区分))?.内容 || '').match(/([0-9]+)月31日まで/)?.[1]);
    const elapsedInsuranceMonths=((closingMonth-insuranceStart+12)%12)+1;
    const allowance=receivables*allowanceRate, allowanceExpense=allowance-creditBalances.貸倒引当金, insurance=debitBalances.保険料*elapsedInsuranceMonths/12;
    const netIncome=sales-cost-allowanceExpense-depreciation-insurance-accruedWages-tax;
    const totalAssets=debitBalances.現金+(receivables-allowance)+endingInventory+(debitBalances.備品-creditBalances.減価償却累計額-depreciation)+(debitBalances.保険料-insurance);
    const totalEquityLiabilities=creditBalances.買掛金+unrecordedPurchases+accruedWages+tax+creditBalances.資本金+creditBalances.繰越利益剰余金+netIncome;
    derivedCells={sales,cost,allowanceExpense,depreciation,insurance,accruedWages,tax,netIncome,totalAssets,totalEquityLiabilities};
    statements={plDebit:cost+allowanceExpense+depreciation+insurance+accruedWages+tax+netIncome,plCredit:sales,bsDebit:totalAssets,bsCredit:totalEquityLiabilities};
  } else if (/統合決算B/.test(item.category)) {
    const balances=String(material('整理前残高')?.内容 || ''), adjustments=String(material('決算整理事項')?.内容 || '');
    const taxRateMatch=String(item.question || '').match(/標準税率\s*([0-9.]+)%/); const taxRate=taxRateMatch ? Number(taxRateMatch[1])/100 : Number.NaN;
    if (!Number.isFinite(taxRate)) errors.push('標準税率が回答開始前の問題文に明示されていません');
    const cashBook=numberAfter(balances,'現金実査前帳簿'), inputVat=numberAfter(balances,'仮払消費税'), outputVat=numberAfter(balances,'仮受消費税');
    const baseSales=numberAfter(balances,'売上'), openingInventory=numberAfter(balances,'期首商品'), basePurchases=numberAfter(balances,'仕入');
    const cashAfter=numberAfter(adjustments,'現金実査額'), unrecordedSales=numberAfter(adjustments,'売上'), unrecordedPurchases=numberAfter(adjustments,'仕入');
    const endingInventory=numberAfter(adjustments,'期末商品'), correctedEquipment=numberAfter(adjustments,'備品（訂正後'), advertising=numberAfter(adjustments,'広告費');
    const accruedIncome=numberAfter(adjustments,'受取手数料'), accruedWages=numberAfter(adjustments,'給料'), tax=numberAfter(adjustments,'法人税等');
    const sales=baseSales+unrecordedSales, purchases=basePurchases+unrecordedPurchases, cost=openingInventory+purchases-endingInventory;
    const depreciationRate=numberAfter(adjustments,'年')/100;
    const saleEvent={type:'unrecordedCashSale',netAmount:unrecordedSales,taxRate,taxMethod:'exclusive'};
    const saleJournal=journalEffectsForEvent(saleEvent);
    const cashReceipt=saleJournal?.cashReceipt, cashShortage=cashBook+cashReceipt-cashAfter;
    const vatPayable=(outputVat+unrecordedSales*taxRate)-(inputVat+unrecordedPurchases*taxRate);
    const baseFees=numberAfter(balances,'受取手数料'), baseWages=numberAfter(balances,'給料');
    const depreciation=correctedEquipment*depreciationRate;
    const netIncome=sales+baseFees+accruedIncome-cost-advertising-depreciation-baseWages-accruedWages-cashShortage-tax;
    derivedCells={cashAfter,cashShortage,sales,purchases,cost,advertising,depreciation,vatPayable,accruedIncome,accruedWages,tax,netIncome};
    if (![cashReceipt,cashShortage,depreciation,netIncome].every(Number.isFinite) || cashShortage < 0) errors.push('取引イベントから現金・消費税・雑損・利益へ一貫して調整できません');
  } else if (/統合決算C/.test(item.category)) {
    const balances=String(material('整理前残高')?.内容 || ''), adjustments=String(material('決算整理事項')?.内容 || '');
    const receivables=numberAfter(balances,'売掛金'), priorAllowance=numberAfter(balances,'貸倒引当金'), loan=numberAfter(balances,'借入金'), rent=numberAfter(balances,'受取家賃');
    const allowanceRate=numberAfter(adjustments,'売掛金の')/100, interestRate=numberAfter(adjustments,'年利')/100;
    const closingMonth=Number(String(item.materials?.find(row => /決算日/.test(row.資料区分))?.内容 || '').match(/決算日([0-9]+)月/)?.[1]);
    const rentStartMonth=Number(adjustments.match(/受取家賃は([0-9]+)月1日/)?.[1]);
    const currentMonths=((closingMonth-rentStartMonth+12)%12)+1;
    const newAsset=numberAfter(adjustments,'7月1日取得の備品'), usefulLife=numberAfter(adjustments,'耐用年数'), interestReceivable=numberAfter(adjustments,'未収利息'), tax=numberAfter(adjustments,'法人税等');
    const oldAsset=numberAfter(adjustments,'従来備品'), oldAnnual=numberAfter(adjustments,'年額'), soldCost=numberAfter(adjustments,'原価'), soldPriorAccum=numberAfter(adjustments,'期首累計');
    const soldPriceMatch=adjustments.match(/を([0-9,]+)円で売却/), soldPrice=soldPriceMatch ? Number(soldPriceMatch[1].replace(/,/g,'')) : Number.NaN;
    const soldCurrentDep=numberAfter(adjustments,'当期6か月分');
    const loanMonth=Number(adjustments.match(/借入金は([0-9]+)月1日借入/)?.[1]);
    const interestMonths=((closingMonth-loanMonth+12)%12)+1;
    const acquisitionMonthMatch=adjustments.match(/([0-9]+)月1日取得の備品/), acquisitionMonth=Number(acquisitionMonthMatch?.[1]), newAssetMonths=((closingMonth-acquisitionMonth+12)%12)+1;
    const allowanceExpense=receivables*allowanceRate-priorAllowance, interest=loan*interestRate*interestMonths/12, rentRevenue=rent*currentMonths/6;
    const oldAssetDepreciation=oldAnnual*(oldAsset-soldCost)/oldAsset, saleLoss=soldCost-soldPriorAccum-soldCurrentDep-soldPrice;
    derivedCells={allowanceExpense,interestExpense:interest,interestPayable:interest,rentRevenue,rentUnearned:rent-rentRevenue,newAssetDepreciation:newAsset/usefulLife*newAssetMonths/12,oldAssetDepreciation,saleLoss,interestReceivable,tax};
  }
  if (!/決算日|会計期間/.test(text)) errors.push('会計期間または決算日が表示されていません');
  if (trialBalance && trialBalance.debit!==trialBalance.credit) errors.push(`整理前貸借不一致 ${trialBalance.debit}/${trialBalance.credit}`);
  if (statements && statements.plDebit!==statements.plCredit) errors.push(`P/L不一致 ${statements.plDebit}/${statements.plCredit}`);
  if (statements && statements.bsDebit!==statements.bsCredit) errors.push(`B/S不一致 ${statements.bsDebit}/${statements.bsCredit}`);
  if (!derivedCells) errors.push('表示資料から独立再計算する会計規則が未実装です');
  return Object.freeze({valid:errors.length===0,errors:Object.freeze(errors),derivedCells:derivedCells&&Object.freeze(derivedCells),trialBalance,statements});
}
function validateAuthoredAnswer(expected, authoredAnswer) {
  const errors=[];
  if(!expected)errors.push('表示資料から独立再計算する会計規則が未実装です');
  else for(const [cell,value] of Object.entries(expected))if(authoredAnswer?.cells?.[cell]!==value)errors.push(`${cell}を表示資料から再計算した値と正答が不一致`);
  return Object.freeze({valid:errors.length===0,errors:Object.freeze(errors)});
}
function validateExamQuestion3(item) {
  const derivation=deriveExamQuestion3Expected(item);
  if(!derivation.derivedCells)return derivation;
  const answerValidation=validateAuthoredAnswer(derivation.derivedCells,item.answer);
  const errors=Object.freeze([...derivation.errors,...answerValidation.errors]);
  return Object.freeze({...derivation,valid:errors.length===0,errors,authoredAnswerMatch:answerValidation.valid});
}

const QuestionDataMeta = Object.freeze({
  "datasetId": "boki3-accounting-rpg-300",
  "dataVersion": "2026.08.24-r3",
  "examScopeVersion": "2026",
  "questionCount": 300,
  "typeCounts": {
    "journal": 150,
    "ledger": 50,
    "trial_balance": 40,
    "correction": 20,
    "worksheet": 20,
    "financial_statement": 10,
    "comprehensive": 10
  },
  "timelinePolicy": {
    "J001-J050": "本編。4月から3月へ一方向に進む。",
    "J051-J100": "復習編。物語上の月を巻き戻さず、水野先輩の確認ケースとして扱う。",
    "J101-J150": "応用編。特定月に固定しない独立ケース。"
  },
  "editorialPolicy": [
    "問題文だけで正答を一意に判断できる条件を記載する。",
    "商品代金と付随費用、負担者と支払者、決議と支払など時点・主体を分離して記述する。",
    "ヒントや解説にしか存在しない正答前提を作らない。",
    "同一原則の反復は数値変更だけでなく、文脈・資料・判断条件を変えて転移学習を促す。",
    "決算前の月に決算論点を扱う場合は、前期資料または予行演習であることをStory Layerに明示する。"
  ]
});

function validateQuestionData(questionData = QuestionData) {
  const errors = [];
  const warnings = [];
  const entries = Object.entries(questionData || {});
  const expectedTypeCounts = {
    journal: 150,
    ledger: 50,
    trial_balance: 40,
    correction: 20,
    worksheet: 20,
    financial_statement: 10,
    comprehensive: 10
  };

  if (entries.length !== 300) {
    errors.push(`問題数が300件ではありません: ${entries.length}`);
  }

  const typeCounts = {};
  const seenIds = new Set();

  for (const [key, item] of entries) {
    if (!item || typeof item !== 'object') {
      errors.push(`${key}: 問題オブジェクトが不正です`);
      continue;
    }
    if (item.id !== key) {
      errors.push(`${key}: キーとidが一致しません (${item.id})`);
    }
    if (seenIds.has(item.id)) {
      errors.push(`${key}: idが重複しています (${item.id})`);
    }
    seenIds.add(item.id);
    typeCounts[item.type] = (typeCounts[item.type] || 0) + 1;

    for (const field of ['id', 'type', 'category', 'difficulty', 'chapter', 'scene', 'story', 'question', 'answer', 'explanation']) {
      if (!(field in item)) errors.push(`${key}: ${field} がありません`);
    }

    if (item.type === 'journal') {
      const debit = Array.isArray(item.answer?.debit) ? item.answer.debit : [];
      const credit = Array.isArray(item.answer?.credit) ? item.answer.credit : [];
      const debitTotal = debit.reduce((sum, row) => sum + Number(row?.amount || 0), 0);
      const creditTotal = credit.reduce((sum, row) => sum + Number(row?.amount || 0), 0);
      if (!debit.length || !credit.length) {
        errors.push(`${key}: 借方または貸方の正答が空です`);
      }
      if (debitTotal !== creditTotal) {
        errors.push(`${key}: 貸借不一致 ${debitTotal} != ${creditTotal}`);
      }
      for (const row of [...debit, ...credit]) {
        if (!row?.account || !Number.isFinite(Number(row?.amount)) || Number(row.amount) <= 0) {
          errors.push(`${key}: 仕訳行が不正です`);
        }
      }
    } else {
      const inputCells = Array.isArray(item.table?.inputCells) ? item.table.inputCells : [];
      const answerCells = item.answer?.cells && typeof item.answer.cells === 'object' ? item.answer.cells : {};
      const renderedInputs = (item.table?.rows || []).flatMap(row => Object.values(row)).filter(value => value === '入力').length;
      if (!item.table || !Array.isArray(item.table.columns) || !Array.isArray(item.table.rows) || renderedInputs !== inputCells.length) errors.push(`${key}: table構造または入力セル数が不正です`);
      if (new Set(inputCells).size !== inputCells.length || Object.keys(answerCells).length !== inputCells.length) errors.push(`${key}: inputCellsとanswer.cellsのキーが一致しません`);
      for (const cell of inputCells) {
        if (!(cell in answerCells)) {
          errors.push(`${key}: 入力セル ${cell} の正答がありません`);
        }
        const inputType = item.table.inputTypes?.[cell] || 'amount';
        if (!['amount', 'text', 'account'].includes(inputType)) errors.push(`${key}: 入力セル ${cell} の型が不正です`);
        if ((inputType === 'amount') !== (typeof answerCells[cell] === 'number')) errors.push(`${key}: 入力セル ${cell} の型と正答型が一致しません`);
      }
    }
  }

  for (const [type, expected] of Object.entries(expectedTypeCounts)) {
    if ((typeCounts[type] || 0) !== expected) {
      errors.push(`${type}: 件数が不正です ${(typeCounts[type] || 0)} / ${expected}`);
    }
  }

  // Story chapter is authored semantic metadata. Chapter volume may be uneven,
  // but every question must belong to a valid April-to-March chapter and all
  // twelve chapters must remain represented. Story-only reachability is guarded
  // separately by the Issue #180 Story authority regression.
  const invalidChapterIds = Object.values(questionData)
    .filter(item => !Number.isInteger(item.chapter) || item.chapter < 1 || item.chapter > 12)
    .map(item => item.id);
  if (invalidChapterIds.length) {
    errors.push(`章番号が1〜12の範囲外です: ${invalidChapterIds.join(',')}`);
  }
  const chapterCounts = Object.values(questionData).reduce((counts, item) => {
    if (Number.isInteger(item.chapter) && item.chapter >= 1 && item.chapter <= 12) {
      counts[item.chapter] = (counts[item.chapter] || 0) + 1;
    }
    return counts;
  }, {});
  const chapterSizes = Array.from({ length:12 }, (_, index) => chapterCounts[index + 1] || 0);
  if (chapterSizes.some(size => size === 0)) {
    errors.push(`12章のいずれかが空です: ${chapterSizes.join(',')}`);
  }

  // 決算整理表: 間接法なのに「備品（取得原価）」を直接調整するように見せない。
  for (let n = 1; n <= 20; n += 1) {
    const id = `D${String(n).padStart(3, '0')}`;
    const item = questionData[id];
    if (!item) continue;
    const text = JSON.stringify(item);
    if (text.includes('備品（取得原価）')) {
      errors.push(`${id}: 間接法の表に旧ラベル「備品（取得原価）」が残っています`);
    }
    if (text.includes('間接法') && !String(item.explanation || '').includes('備品勘定そのものを減額しません')) {
      warnings.push(`${id}: 間接法の表示上の注意がありません`);
    }
  }

  // 貸借対照表: 差額計算が成立する限定条件を明示する。
  for (let n = 1; n <= 10; n += 1) {
    const id = `F${String(n).padStart(3, '0')}`;
    const item = questionData[id];
    if (!item) continue;
    if (!String(item.question || '').includes('表に示した項目以外')) {
      errors.push(`${id}: 他の項目がないという限定条件がありません`);
    }
  }

  // 総合問題: 10問すべて同一資料になっていないことを確認。
  const comprehensiveSignatures = [];
  for (let n = 1; n <= 10; n += 1) {
    const id = `C${String(n).padStart(3, '0')}`;
    const item = questionData[id];
    if (item) comprehensiveSignatures.push(JSON.stringify(item.materials || []));
  }
  if (new Set(comprehensiveSignatures).size !== comprehensiveSignatures.length) {
    errors.push('C001-C010: 総合問題の資料が重複しています');
  }

  return Object.freeze({
    ok: errors.length === 0,
    errors: Object.freeze(errors),
    warnings: Object.freeze(warnings),
    counts: Object.freeze({ total: entries.length, ...typeCounts })
  });
}

function validateSemanticQuestionData(questionData = QuestionData) {
  const errors = []; const findings = {}; const eligibleIds = []; const entries = Object.entries(questionData || {}); const order = new Map();
  const flow = { journal:0, ledger:1, trial_balance:2, correction:3, worksheet:4, financial_statement:5, comprehensive:6 };
  entries.map(([id, item], index) => ({ id, item, index })).sort((a, b) => a.item.chapter - b.item.chapter || flow[a.item.type] - flow[b.item.type] || a.index - b.index).forEach(({ id }, index) => order.set(id, index));

  const visibleText = item => JSON.stringify({ question:item.question, story:item.story, materials:item.materials, adjustments:item.adjustments, fixedCells:item.table?.rows });
  const visibleNumbers = item => [...visibleText(item).matchAll(/\d[\d,]*(?:\.\d+)?/g)]
    .map(match => Number(match[0].replace(/,/g, ''))).filter(number => Number.isFinite(number) && number > 0);
  const answerNumbers = item => item.type === 'journal'
    ? [...(item.answer?.debit || []), ...(item.answer?.credit || [])].map(row => row.amount)
    : Object.values(item.answer?.cells || {}).filter(value => typeof value === 'number');
  const canDerive = (target, inputs, text, allowRates = true) => {
    if (inputs.includes(target)) return true;
    const limit = Math.max(target * 4, 10000000);
    // まず、表示された各数値を一度ずつ使う合計・差額を検証する（同額2件も保持）。
    let reachable = new Set([0]);
    for (const number of inputs) {
      const next = new Set(reachable);
      for (const total of reachable) {
        if (Math.abs(total + number) <= limit) next.add(total + number);
        if (Math.abs(total - number) <= limit) next.add(total - number);
      }
      reachable = next;
      if (reachable.has(target)) return true;
      if (reachable.size > 20000) reachable = new Set([...reachable].sort((a,b) => Math.abs(a-target) - Math.abs(b-target)).slice(0,10000));
    }
    // 掛け算・割り算は率、数量、単価を扱う表形式問題だけに限定する。
    // 仕訳では同じ表示額の再利用による 48,000×48,000 等を許可しない。
    if (!allowRates) return false;
    let values = new Set(inputs);
    for (let round = 0; round < 2; round += 1) {
      const current = [...values].slice(0, 160);
      for (const left of current) for (const right of current) {
        for (const result of [left + right, Math.abs(left - right), left * right, right ? left / right : NaN, (text.includes('%') || text.includes('％')) ? left * right / 100 : NaN]) {
          if (Number.isInteger(result) && result >= 0 && result <= limit) values.add(result);
        }
      }
      if (values.has(target)) return true;
    }
    return false;
  };

  for (const [id, item] of entries) {
    const itemErrors = [];
    const semantic = item.semantic;
    if (!semantic || semantic.questionId !== id) itemErrors.push('semantic入力契約がありません');
    const allowedSources = new Set(['question','story','materials','fixedCell']);
    for (const source of semantic?.visibleInputs || []) if (!allowedSources.has(source)) itemErrors.push(`非表示source ${source} に依存しています`);
    if (!String(item.question || '').trim()) itemErrors.push('表示する問題文がありません');
    const inputs = visibleNumbers(item); const text = visibleText(item);
    const independentlyCalculated = item.type === 'journal' ? independentlyDerivedJournal(item) : independentlyDerivedTableCells(item);
    const ruleDerivedNumbers = new Set(item.type === 'journal' ? [...(independentlyCalculated?.debit || []), ...(independentlyCalculated?.credit || [])].map(row => row.amount) : Object.values(independentlyCalculated || {}).filter(value => typeof value === 'number'));
    for (const answer of new Set(answerNumbers(item))) {
      if (!Number.isFinite(answer) || (answer < 0 && item.format !== 'exam-question-3')) itemErrors.push(`正答金額 ${answer} が不正です`);
      else if (answer > 0 && item.format !== 'exam-question-3' && !ruleDerivedNumbers.has(answer) && !canDerive(answer, inputs, text, item.type !== 'journal' || /[%％]|耐用年数|定額法|率/.test(text))) itemErrors.push(`正答金額 ${answer} を表示数値から導出できません`);
    }
    if (item.format === 'exam-question-3') itemErrors.push(...validateExamQuestion3(item).errors);
    if (answerFingerprint(item.answer) !== ReviewedAnswerFingerprints[id]) itemErrors.push('レビュー済みanswer fingerprintと一致しません');
    if (item.type === 'journal') {
      const expectedJournal = SemanticJournalAnswerKey.get(id);
      const actualJournal = JSON.stringify({ debit:item.answer?.debit || [], credit:item.answer?.credit || [] });
      if (!expectedJournal || actualJournal !== expectedJournal) itemErrors.push('レビュー済み仕訳キーと勘定科目・金額が一致しません');
      const debit = (item.answer?.debit || []).reduce((sum,row) => sum + Number(row.amount || 0), 0);
      const credit = (item.answer?.credit || []).reduce((sum,row) => sum + Number(row.amount || 0), 0);
      if (!debit || debit !== credit) itemErrors.push(`仕訳の貸借が一致しません (${debit}/${credit})`);
      const independentJournal=independentlyDerivedJournal(item);
      if (independentJournal && actualJournal !== JSON.stringify(independentJournal)) itemErrors.push('表示取引から独立導出した仕訳と一致しません');
    } else {
      const inputsSet = new Set(item.table?.inputCells || []); const answerKeys = Object.keys(item.answer?.cells || {});
      if (inputsSet.size !== answerKeys.length || answerKeys.some(key => !inputsSet.has(key))) itemErrors.push('表示入力欄と正答キーが一致しません');
      const expectedCells = SemanticTableAnswerKey.get(id);
      if (!expectedCells || JSON.stringify(item.answer?.cells || {}) !== expectedCells) itemErrors.push('レビュー済みセルキーと金額・科目が一致しません');
      const independentCells = independentlyDerivedTableCells(item);
      if (independentCells && JSON.stringify(item.answer?.cells || {}) !== JSON.stringify(independentCells)) itemErrors.push('表示資料から独立計算した正答と一致しません');
    }
    const links = item.knowledgeLinks || {};
    for (const relation of ['prerequisite','nextConcept']) if ((links[relation] || []).includes(id)) itemErrors.push(`${relation}がself-loopです`);
    if (new Set(links.related || []).size !== (links.related || []).length) itemErrors.push('relatedが重複しています');
    for (const prerequisite of links.prerequisite || []) if (!order.has(prerequisite) || order.get(prerequisite) >= order.get(id)) itemErrors.push(`prerequisite ${prerequisite}が学習順を逆転しています`);
    const status = itemErrors.length ? 'INVALID' : 'VALID';
    findings[id] = Object.freeze({ status, errors:Object.freeze(itemErrors), visibleNumbers:Object.freeze(inputs) });
    if (status === 'VALID') eligibleIds.push(id);
    itemErrors.forEach(error => errors.push(`${id}: ${error}`));
  }
  const validCount = eligibleIds.length;
  return Object.freeze({ ok: errors.length === 0, errors:Object.freeze(errors), findings:Object.freeze(findings), eligibleIds:Object.freeze(eligibleIds), counts:Object.freeze({ VALID:validCount, QUESTIONABLE:0, INVALID:entries.length-validCount }) });
}

