// Gate 4: every final-runtime Chapter 8 ledger receives structured wrong-answer
// guidance. Existing authored models (L034/L041) remain authoritative; the
// remaining questions override only the reasoning summary and use generated
// sources/calculation/transfer/check/mistake evidence.
const chapter8ExplanationSummary = item => {
  const format = item.format || '';
  const category = String(item.category || '');
  if (format === 'fixed-asset-ledger' || /固定資産台帳/u.test(category)) return '取得原価・耐用年数・償却方法・使用月数を先に確認し、年額→月割→帳簿価額の順に処理します。';
  if (format === 'journal-book' || /仕訳帳/u.test(category)) return '取引ごとに増減する勘定科目を決め、借方・貸方・元丁を日付順に仕訳帳へ記入します。';
  if (format === 'bookkeeping-notes-receivable') return '受取手形記入帳の対象になる約束手形だけを選び、受取日・振出人・満期日・金額を資料で確認します。';
  if (format === 'bookkeeping-notes-payable') return '自店が振り出した約束手形だけを選び、振出日・受取人・満期日・金額を資料で確認します。';
  if (format === 'bookkeeping-cash-book') return '現金の受入と支払を分け、受入額－支払額で残高の動きを追います。';
  if (format === 'bookkeeping-checking-book') return '当座預金の預入と引出を分け、預入額－引出額で残高の動きを追います。';
  if (format === 'bookkeeping-petty-cash-book') return '支払内容を費用科目ごとに分類し、定額資金前渡法では支払額と補給額の関係を確認します。';
  if (format === 'bookkeeping-purchase-book') return '仕入と仕入返品を分け、総仕入高から返品額を差し引いて純仕入高を求めます。';
  if (format === 'bookkeeping-sales-book') return '売上と売上返品を分け、総売上高から返品額を差し引いて純売上高を求めます。';
  if (format === 'bookkeeping-inventory-ledger' || /商品有高帳/u.test(category)) return '数量と単価を別々に追い、指定された払出単価の計算方法で払出額と残高額を求めます。';
  if (format === 'bookkeeping-voucher-entry') return '現金が増えるか、減るか、動かないかを確認して、使う伝票を決めます。';
  if (format === 'bookkeeping-general-ledger' || format === 'bookkeeping-account-ledger' || /元帳/u.test(category)) return 'その勘定がどちら側で増えるかを確認し、取引ごとの増減と相手勘定を残高へ反映します。';
  return '資料を順に確認し、必要な金額を帳簿のどこに記入するか決めます。';
};
Object.values(QuestionData).forEach(item => {
  if (item.type !== 'ledger' || item.explanationModel) return;
  item.explanationModel = {summary:[{text:chapter8ExplanationSummary(item)}]};
});

const gate5ExplanationSummary = item => {
  if (item.type === 'journal') return '取引で何が増え、何が減ったかを確認し、勘定科目を決めて借方・貸方に分けます。';
  if (item.type === 'ledger') return chapter8ExplanationSummary(item);
  if (item.type === 'trial_balance') return '各勘定の残高を借方と貸方に分け、それぞれを縦に合計します。';
  if (item.type === 'correction') return '帳簿の記録と証ひょうを比べ、誤っている部分だけを訂正します。';
  if (item.type === 'worksheet') return '試算表の残高を出発点に、決算整理を反映し、損益計算書と貸借対照表へ振り分けます。';
  if (item.type === 'financial_statement') return '決算整理後の金額を収益・費用・資産・負債・純資産に分け、必要な合計や利益を求めます。';
  if (item.type === 'comprehensive') return '資料を処理する順番を整理し、仕訳・転記・決算整理をつないで最終金額を求めます。';
  return '';
};
Object.values(QuestionData).forEach(item => {
  if (item.explanationModel || !['journal','ledger','trial_balance','correction','worksheet','financial_statement','comprehensive'].includes(item.type)) return;
  item.explanationModel = {summary:[{text:gate5ExplanationSummary(item)}]};
});

// Issue #161 explanation rollout cohorts are historical implementation batches,
// not semantic Story chapters. Keep them independent from authored chapter routing.
const inQuestionRange = (item, prefix, start, end) =>
  item.id.startsWith(prefix) && Number(item.id.slice(1)) >= start && Number(item.id.slice(1)) <= end;

// PR-C: J001-J075.
Object.values(QuestionData).forEach(item => {
  if (inQuestionRange(item, 'J', 1, 75)) item.teachingPresentation = 'structured-always';
});

// PR-D: J076-J150.
Object.values(QuestionData).forEach(item => {
  if (inQuestionRange(item, 'J', 76, 150)) item.teachingPresentation = 'structured-always';
});

// PR-E: all ledger questions L001-L050.
Object.values(QuestionData).forEach(item => {
  if (inQuestionRange(item, 'L', 1, 50)) item.teachingPresentation = 'structured-always';
});

// PR-F: T001-T040, E001-E010 and C001-C010.
Object.values(QuestionData).forEach(item => {
  if (inQuestionRange(item, 'T', 1, 40) ||
      inQuestionRange(item, 'E', 1, 10) ||
      inQuestionRange(item, 'C', 1, 10)) {
    item.teachingPresentation = 'structured-always';
  }
});

// PR-G: E011-E020, D001-D020 and F001-F010.
Object.values(QuestionData).forEach(item => {
  if (inQuestionRange(item, 'E', 11, 20) ||
      inQuestionRange(item, 'D', 1, 20) ||
      inQuestionRange(item, 'F', 1, 10)) {
    item.teachingPresentation = 'structured-always';
  }
});

// L044/L045: the opening amount is a condition of these exercises, not a
// general rule for cash/checking books. Apply after all runtime replacements.
for (const [id, month, endDay, account, plus, minus, incoming, outgoing] of [
  ['L044',4,5,'現金','受入','支払',50000,18000],
  ['L045',5,8,'当座預金','預入','引出',300000,85000]
]) {
  const q=QuestionData[id], start=`${month}月1日`, end=`${month}月${endDay}日`;
  const before=id==='L045'?'（同日の預入前）':'';
  q.question=`過去の${start}から${end}までの出納帳資料を点検します。${start}の記帳開始時点${before}の${account}残高は0円です。この期間の${account}の増減に関する取引は、下記資料の2件がすべてです。${plus}額・${minus}額と${end}の取引後残高を記入しなさい。`;
  const inc=incoming.toLocaleString('ja-JP'), dec=outgoing.toLocaleString('ja-JP'), balance=(incoming-outgoing).toLocaleString('ja-JP');
  const formula=`0 ＋ ${inc} − ${dec} = ${balance}`;
  q.explanation=`【使用する資料】${start}の開始残高0円（前残）は、この問題で指定された条件です。【計算と転記】${account}の増加を${plus}欄、減少を${minus}欄へ記入します。資料の2件が期間内の全取引なので、開始残高0円＋${plus}${inc}円−${minus}${dec}円＝${end}の取引後残高${balance}円です（${formula}）。開始残高がある別の問題では、その金額から計算します。`;
  q.explanationModel={
    calculation:[
      {label:`${plus}額：${account}の増加`,expression:null,result:incoming,operands:[],evidenceRefs:['materials[0]']},
      {label:`${minus}額：${account}の減少`,expression:null,result:outgoing,operands:[],evidenceRefs:['materials[1]']},
      {label:`${end}の取引後残高：開始残高0円（本問の条件）＋${plus}−${minus}`,expression:formula,result:incoming-outgoing,operands:[{label:'開始残高',value:0},{label:plus,value:incoming},{label:minus,value:outgoing}],evidenceRefs:['question','materials']}
    ],
    checks:[{label:'開始残高と取引範囲を確認する',expected:`開始残高はいつも0円とは限りません。本問は${start}の開始残高0円と期間内の全取引が指定されているため、${end}の残高を一意に求められます。`,evidenceRefs:['question','materials']}]
  };
}

// Top-level `const` declarations are not added to `window` in classic scripts.
// Expose the data explicitly because the application bootstrap reads it there.
if (typeof window !== 'undefined') {
  // The exam pool is an explicit assessment contract. It is intentionally independent
  // of object insertion order and is consumed by both Controller and the audits.
  window.WorkCaseNarratives = WorkCaseNarratives;
  window.AnchorScenes = AnchorScenes;
  window.ExamPoolDefinition = ExamPoolDefinition;
  window.QuestionData = QuestionData;
  window.validateQuestionData = validateQuestionData;
  window.validateSemanticQuestionData = validateSemanticQuestionData;
  window.validateExamQuestion3 = validateExamQuestion3;
  window.deriveExamQuestion3Expected = deriveExamQuestion3Expected;
  window.validateAuthoredAnswer = validateAuthoredAnswer;
  window.journalEffectsForEvent = journalEffectsForEvent;
  window.independentlyDerivedTableCells = independentlyDerivedTableCells;
  window.independentlyDerivedJournal = independentlyDerivedJournal;
}